<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ExternalApiController extends Controller{public function status(Request$r){return response()->json(['success'=>true,'data'=>['service'=>'Deurstore API','company_id'=>$r->attributes->get('integration_company_id'),'time'=>now()->toIso8601String()]]);}public function products(Request$r){$c=$r->attributes->get('integration_company_id');$q=DB::table('products as p')->leftJoin('stocks as s','s.product_id','=','p.id')->where(['p.company_id'=>$c,'p.status'=>'active'])->select('p.id','p.sku','p.barcode','p.name','p.category','p.brand','p.unit_type','p.sale_price',DB::raw('COALESCE(SUM(s.quantity),0) stock'))->groupBy('p.id');if($r->search)$q->where('p.name','like',"%{$r->search}%");return response()->json(['success'=>true,'data'=>$q->paginate(min(100,max(1,(int)$r->input('per_page',25))))]);}public function sales(Request$r){$c=$r->attributes->get('integration_company_id');$q=DB::table('sales')->where('company_id',$c)->select('id','number','document_type','subtotal','discount','tax','total','status','created_at');if($r->from)$q->whereDate('created_at','>=',$r->from);if($r->to)$q->whereDate('created_at','<=',$r->to);return response()->json(['success'=>true,'data'=>$q->latest()->paginate(min(100,max(1,(int)$r->input('per_page',25))))]);}}
